import{_ as a,c as t,o as n,ae as i}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"Numeric Value","description":"Numeric Value","frontmatter":{"title":"Numeric Value","description":"Numeric Value"},"headers":[],"relativePath":"guide/field-types/numeric-value.md","filePath":"guide/field-types/numeric-value.md"}'),o={name:"guide/field-types/numeric-value.md"};function l(r,e,s,u,c,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="numeric-value" tabindex="-1">Numeric Value <a class="header-anchor" href="#numeric-value" aria-label="Permalink to &quot;Numeric Value&quot;">​</a></h1><p>The Numeric Value data type in Ninja Tables is for columns with numeric data. A data table can have dynamic data to visualize the right message and Ninja Tables does it perfectly. Learn how to add numeric data in tables. You can decide the data type right from the start when you add a column to the table. From your dashboard, go to the Ninja Tables plugin → Tables (the table where you want to add Column) → Add Column.</p><ul><li>A pop-up form will appear, and you will see the available <strong>Data Type</strong> here. You can choose from the various data types listed in the below screenshot. <img src="https://ninjatables.com/wp-content/uploads/2022/11/data-types-1024x612.png" alt="table column data types"></li></ul><h2 id="numeric-value-data-type" tabindex="-1">Numeric Value Data Type <a class="header-anchor" href="#numeric-value-data-type" aria-label="Permalink to &quot;Numeric Value Data Type&quot;">​</a></h2><p>If you only want numbers in the input field of a column in Ninja Tables, then choose Numeric Value as the data type. It can restrict your input only in the number field. The data can be sorted using the numeric value in ascending or descending order.</p><ul><li>Go to the <strong>Data Type</strong> option and select the **Numeric Value **type of the column and add a column.</li><li>Now a new column with data type has been added to the table. To see this data type, click on the <strong>Edit icon</strong> (right side of the table column). A window will appear then. See the below screenshot – <img src="https://ninjatables.com/wp-content/uploads/2023/09/Numeric-Value.png" alt="Numeric Value data type"></li></ul><h3 id="separator-style-in-numeric-value-data" tabindex="-1">Separator Style in Numeric Value Data <a class="header-anchor" href="#separator-style-in-numeric-value-data" aria-label="Permalink to &quot;Separator Style in Numeric Value Data&quot;">​</a></h3><p>This data type supports two types of Separator Styles- US Style and European Style. If you input 123,234,01 and use the <strong>European style</strong>, Ninja Tables will maintain its sorting based on that and show the numeric values with a <strong>decimal comma</strong>. Whereas in the <strong>US style</strong>, the separator will be a <strong>decimal point</strong> and it will be 123,234.01. <img src="https://ninjatables.com/wp-content/uploads/2023/09/Separator-style-in-numeric-value-1024x392.png" alt="Separator style in numeric value"> This setting is for maintaining numeric calculations and logic around tables. It does not change the display format of the numbers in the table. This is how you can add <strong>Numeric</strong> <strong>Values</strong> to your column easily!</p>',8)])])}const h=a(o,[["render",l]]);export{p as __pageData,h as default};
